describe('Snackbar notification on clipboard copy', () => {
  beforeEach(() => {
    cy.visit('/')
    cy.viewport(1280, 720)
  })

  it('should display snackbar message when text is copied to clipboard', () => {
    // Find and interact with a copyable element
    cy.get('[data-testid="copy-button"]').should('be.visible').click()

    // Verify snackbar appears
    cy.get('[data-testid="snackbar"]')
      .should('be.visible')
      .and('contain', 'Copied to clipboard')

    // Verify snackbar has correct styling
    cy.get('[data-testid="snackbar"]')
      .should('have.css', 'position', 'fixed')
      .and('have.css', 'bottom')

    // Verify snackbar auto-dismisses after timeout (default 3000ms)
    cy.get('[data-testid="snackbar"]')
      .should('be.visible')

    cy.wait(3500)

    cy.get('[data-testid="snackbar"]')
      .should('not.exist')
  })

  it('should copy correct text to clipboard and show snackbar with custom message', () => {
    const testText = 'Hello, World!'

    // Set up clipboard spy
    cy.window().then((win) => {
      cy.stub(win.navigator.clipboard, 'writeText').resolves()
    })

    // Find element with specific text to copy
    cy.get('[data-testid="copy-button"][data-copy-text="' + testText + '"]')
      .should('be.visible')
      .click()

    // Verify clipboard.writeText was called with correct text
    cy.window().then((win) => {
      expect(win.navigator.clipboard.writeText).to.have.been.calledWith(testText)
    })

    // Verify snackbar appears with correct message
    cy.get('[data-testid="snackbar"]')
      .should('be.visible')
      .and('contain', 'Copied to clipboard')

    // Verify snackbar has success styling
    cy.get('[data-testid="snackbar"]')
      .should('have.class', 'snackbar-success')
  })

  it('should handle multiple rapid copy clicks without stacking snackbars', () => {
    // Click copy button multiple times rapidly
    cy.get('[data-testid="copy-button"]').click()
    cy.get('[data-testid="copy-button"]').click()
    cy.get('[data-testid="copy-button"]').click()

    // Verify only one snackbar is visible at a time
    cy.get('[data-testid="snackbar"]')
      .should('have.length', 1)
      .and('be.visible')
      .and('contain', 'Copied to clipboard')
  })

  it('should display snackbar with error message when clipboard copy fails', () => {
    cy.window().then((win) => {
      cy.stub(win.navigator.clipboard, 'writeText').rejects(new Error('Clipboard access denied'))
    })

    cy.get('[data-testid="copy-button"]').click()

    // Verify error snackbar appears
    cy.get('[data-testid="snackbar"]')
      .should('be.visible')
      .and('contain', 'Failed to copy')

    // Verify error styling
    cy.get('[data-testid="snackbar"]')
      .should('have.class', 'snackbar-error')
  })

  it('should dismiss snackbar when close button is clicked', () => {
    cy.get('[data-testid="copy-button"]').click()

    cy.get('[data-testid="snackbar"]')
      .should('be.visible')

    // Click close button on snackbar
    cy.get('[data-testid="snackbar-close"]')
      .should('be.visible')
      .click()

    // Verify snackbar is removed
    cy.get('[data-testid="snackbar"]')
      .should('not.exist')
  })

  it('should handle copying from different element types', () => {
    // Test copying from input field
    cy.get('[data-testid="copy-input"]')
      .type('Test input text')

    cy.get('[data-testid="copy-input-button"]').click()

    cy.get('[data-testid="snackbar"]')
      .should('be.visible')
      .and('contain', 'Copied to clipboard')

    cy.wait(3500)
    cy.get('[data-testid="snackbar"]').should('not.exist')

    // Test copying from code block
    cy.get('[data-testid="copy-code-button"]').click()

    cy.get('[data-testid="snackbar"]')
      .should('be.visible')
      .and('contain', 'Copied to clipboard')
  })
})
